import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Load font at module level to ensure it's ready before render
const { fontFamily: interFamily } = loadInter();



export type KineticTypographyProps = Record<string, any>;

const KineticTypography: React.FC<KineticTypographyProps> = ({
  backgroundColor = "#111215",
  transparentBackground = false,
  durationInSeconds = 6,
  textColor = "#ffffff",
  accentColor = "#fc3a46",
  prefixText = "This isn't ",
  struckText = "software.",
  secondLineText = "It's infrastructure.",
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080; // responsive scale factor

  // Handle transparency logic before return
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // --- Animation Timings & Interpolations ---
  
  // Line 1 Entrance (Fades and slides up slightly)
  const line1Opacity = interpolate(frame, [10, 25], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  const line1Y = interpolate(frame, [10, 30], [30 * s, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic)
  });

  // Strikethrough (Draws horizontally across the struck word)
  const strikeProgress = interpolate(frame, [40, 55], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic)
  });

  // Line 2 Entrance (Fades and slides up slightly, completing the thought)
  const line2Opacity = interpolate(frame, [70, 85], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  const line2Y = interpolate(frame, [70, 90], [30 * s, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic)
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          gap: `${15 * s}px`,
          fontFamily: interFamily,
          fontWeight: 700,
          fontSize: `${110 * s}px`,
          color: textColor,
          letterSpacing: `-${3 * s}px`,
          lineHeight: 1.1,
          transition: "none", // ensure pure frame-based rendering
        }}
      >
        {/* Line 1 */}
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            opacity: line1Opacity,
            transform: `translateY(${line1Y}px)`,
            whiteSpace: "pre-wrap",
            transition: "none",
          }}
        >
          <span>{prefixText}</span>
          <div style={{ position: "relative", display: "inline-block" }}>
            <span>{struckText}</span>
            
            {/* Animated Strikethrough Line */}
            <div
              style={{
                position: "absolute",
                top: "52%",
                left: "-2%", 
                height: `${10 * s}px`,
                width: `${strikeProgress * 104}%`, 
                backgroundColor: accentColor,
                transform: "translateY(-50%)",
                borderRadius: `${4 * s}px`, 
                transition: "none",
              }}
            />
          </div>
        </div>

        {/* Line 2 */}
        <div
          style={{
            opacity: line2Opacity,
            transform: `translateY(${line2Y}px)`,
            transition: "none",
          }}
        >
          {secondLineText}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default KineticTypography;